head.script:
// 서버 통신 서비스 호출을 위한 Context Path
scwin.CONTEXT_PATH = WebSquare.core.getConfiguration("/WebSquare/wpack/contextRoot/@value");

// 서버 통신 서비스 호출을 위한 Service Url (Context Path 이하 경로)
scwin.SERVICE_URL = "";

// 서버 통신 기본 모드 ( "asynchronous" / "synchronous") - "synchronous"는 비권장 통신 방식임
scwin.DEFAULT_OPTIONS_MODE = "asynchronous";

// 서버 통신 기본 미디어 타입
scwin.DEFAULT_OPTIONS_MEDIATYPE = "application/json";

// GET Method에 대해서 RESTFul 방식으로 URL 생성되도록 하는 옵션 (true : 동작, false : 미동작)
// RESTFul URL 생성 규칙에 관한 자세한 설명은 scwin.setActionParam 함수의 주석 참조
scwin.IS_RESTFUL_URL = true;

// 통신 상태 코드
scwin.MESSAGE_CODE = {
    STATUS_ERROR: "E",
    STATUS_SUCCESS: "S",
    STATUS_WARNING: "W",
    STATUS_INFO: "I"
};

scwin.onpageload = function () {

};

/**
 * @method
 * @name getContextPath
 * @description 전역으로 선언된 Context Path 값을 가져온다.
 * @hidden N
 * @exception 
 * @example $c.sbm.getContextPath();
 */
scwin.getContextPath = function () {
    return scwin.CONTEXT_PATH;
};

/**
 * @method
 * @name __preSubmitFunction
 * @description submission의 공통 설정에서 사용.
 * submisison 통신 직전 호출.
 * return true일 경우 통신 수행, return false일 경우 통신 중단
 * 
 * @param {Object} sbmObj 서브미션 객체
 * @returns {Boolean} 통신수행여부
 * @hidden N
 * @exception 
 */
scwin.__preSubmitFunction = function (sbmObj) {
    if (($c.util.isEmpty(scwin.CONTEXT_PATH) === false) && (sbmObj.action.indexOf(scwin.CONTEXT_PATH) !== 0)) {
        sbmObj.action = scwin.CONTEXT_PATH + sbmObj.action;
    }

    // REST API 방식 처리를 위해서 GET Method에 대해서 Request 데이터를 Path Variable 치환 및 QueryString으로 생성함
    if (scwin.IS_RESTFUL_URL === true) {
        $c.sbm.__setActionParam(sbmObj);
    }
};

/**
 * @method
 * @name __setActionParam
 * @description
 * REST API 방식 처리를 위해서 GET Method에 대해서 Request 데이터를 Path Variable 치환 및 QueryString으로 생성한다.
 * 
 * 1. Path Variable 처리 : Action에서 "/testJsonMap/{procId}/{seq}/"와 같이 Path Variable(${procId}, ${seq})을 선언할 경우, 
 *	 해당 변수를 DataMap이나 RequestData(JSON)에 정의된 Key의 Value으로 치환한다.
 *	 DataMap이나 RequestData(JSON) 안에 Path Variable({procId}, {seq})에 정의된 procId와 seq Key(Column)이 존재해야 한다.
 *	 Key가 존재하지 않을 경우 Path Variable에 추가하지 않는다.
 *	 Path Variable에 추가된 Key 값은 GET 방식일 경우 생성되는 QueryString에서 제외 시킨다.
 *	 
 * 2. QueryString 처리 : GET Method으로 Action을 호출할 경우, 해당 변수를 DataMap이나 RequestData(JSON)에 정의된 Key와 Value으로 치환한다.
 *	 DataMap이나 RequestData(JSON) 안에 Path Variable({procId}, {seq})에 정의된 procId와 seq Key(Column)이 존재해야 한다.
 *	 단 건 데이터(Map)만 QueryString으로 생성해서 서버에 전송하고, Array 형태의 데이터의 경우에는 QueryString으로 포함시키지 않는다.
 *
 * @param {Object} sbmObj Submission 객체
 * @hidden N
 * @exception 
 * @example
// Submission ref 정의된 DataMap의 데이터를 QueryString 방식으로 URL에 추가해서 전달하는 예제 코드
// sbm_submission1.ref = "data:json,dma_dataMap1"
// sbm_submission1.action = "/restful/testJsonMap2"
// 생성된 Request URL : http://127.0.0.1:8080/restful/testJsonMap2.do?procId=PR001&subId=SB002&name=Peter&tel=010-2223-4421
scwin.btn_search1_onclick = function(e) {
    $c.sbm.execute(sbm_submission1);
};

// JSON 객체를 QueryString 방식으로 URL에 추가해서 전달하는 예제 코드
// sbm_submission2.action = "/restful/testJsonMap2"
// 생성된 Request URL : http://127.0.0.1:8080/restful/testJsonMap2.do?procId=PR001&subId=SB002&name=Peter&tel=010-2223-4421
scwin.btn_search2_onclick = function(e) {
    const param = {
        procId : "PR001",
        subId : "SB002",
        name : "Peter",
        tel : "010-2223-4421"
    };
    $c.sbm.execute(sbm_submission2, param);
};	

// ref 정의된 DataMap의 데이터를 Path Variable과 QueryString 방식을 조합해서 URL에 추가해서 전달하는 예제 코드
// DataMap 내에 정의된 Column Id 중에서 Path Variable로 정의되지 않은 컬럼(name, tel)을 QueryString 방식으로 추가된다.
// sbm_submission3.ref = "data:json,dma_dataMap1"
// sbm_submission3.action = "/restful/testJsonMap3/{procId}/{subId}"
// 생성된 Request URL : http://127.0.0.1:8080/restful/testJsonMap3/PR001/SB002?name=Peter&tel=010-2223-4421
scwin.btn_search3_onclick = function(e) {
    $c.sbm.execute(sbm_submission3);
};
 */
scwin.__setActionParam = function (sbmObj) {
    let requestData = sbmObj.requestData || WebSquare.ModelUtil.getRefToReqData(sbmObj);

    if ($c.util.isEmpty(requestData)) {
        return;
    }

    if (typeof requestData === "string") {
        requestData = JSON.parse(requestData);
    }

    if ($c.util.isEmpty(sbmObj.__action)) {
        sbmObj.__action = sbmObj.action;
    }

    let actionUrl = sbmObj.__action;

    let queryParam = {};
    if (sbmObj.__action.indexOf("/{") > -1) {
        actionUrl = actionUrl.substr(0, actionUrl.indexOf("/{"));
    }

    // requestData를 QueryString으로 생성해서 submission.action에 추가한다.
    if ($c.util.isJSON(requestData)) {

        // DataMap에 저장된 데이터를 queryParam에 저장한다.
        for (let key in requestData) {
            if (($c.util.isEmpty(requestData[key]) === false) && ($c.util.isJSON(requestData[key]) === false)) {
                queryParam[key] = encodeURIComponent(requestData[key]);
            } else if (($c.util.isJSON(requestData[key])) && ($c.util.isArray(requestData[key]) === false)) {
                for (let subKey in requestData[key]) {
                    if (($c.util.isEmpty(requestData[key][subKey]) === false) && ($c.util.isJSON(requestData[key][subKey]) === false)) {
                        queryParam[subKey] = encodeURIComponent(requestData[key][subKey]);
                    }
                }
            }
        }

        // URL에 Path Variable(ex. {paramId})로 정의된 변수를 queryParam의 정의된 값으로 치환하고, queryParam에서는 제거한다.
        // queryParam에 Path Variable과 일치하는 값이 없을 경우 Skip한다.
        const actionArr = sbmObj.__action.split(/(\{[^}]*})/g);
        for (let i = 0; i < actionArr.length; i++) {
            if (actionArr[i].match(/(\{[^}]*})/g) !== null) {
                let paramKey = actionArr[i].substr(1, actionArr[i].indexOf("}") - 1);
                if (typeof queryParam[paramKey] !== "undefined") {
                    actionUrl += "/" + queryParam[paramKey];
                    delete queryParam[paramKey];
                }
            }
        }

        // GET Method로 전송할 경우 queryParam에 저장된 Key, Value를 QueryString으로 생성해서 Action URL에 붙인다.
        if (sbmObj.method === "get") {
            for (let key in queryParam) {
                if (actionUrl.indexOf("?") === -1) {
                    actionUrl += "?" + key + "=" + queryParam[key];
                } else {
                    actionUrl += "&" + key + "=" + queryParam[key];
                }
            }
        }

        sbmObj.action = actionUrl;
    }
};


/**
 * @method
 * @name __callbackSubmitFunction
 * @description 모든 submission의 defaultCallback - $c.sbm.submitErrorHandler 보다 먼저 수행됨. (400 Error) config.xml에 설정
 * @param {Object} resObj responseData 객체
 * @param {Object} sbmObj Submission 객체
 * @hidden N
 * @exception 
 */
scwin.__callbackSubmitFunction = function (resObj, sbmObj) {
    // server와 연결을 할 수 없을 경우 responseStatusCode가 0으로 발생.
    if ((resObj.responseStatusCode < 100) || (resObj.responseStatusCode > 599)) {
        let detailStr = "HTTP STATUS INFO";
        detailStr += resObj.responseStatusCode;
        detailStr += " - URI:";
        detailStr += resObj.resourceUri;

        const msgObj = {
            statusCode: "E",
            errorCode: resObj.responseStatusCode,
            message: "서버와 연결할 수 없습니다. 자세한 내용은 관리자에게 문의하시기 바랍니다.",
            messageDetail: detailStr
        };

        $c.sbm.resultMsg(msgObj);
        return false;
    }

    // executeDynamic gridview : 통신 성공 시, refresh 대상 grid(들)를 자동 바인딩(__bindResponseToTargets) 호출 직전에 초기화(initGrid)한다.
    // gridview는 단일(컴포넌트 ID 문자열 또는 컴포넌트 객체)뿐 아니라 콤마(,)로 구분한 다중 ID 문자열("grd_main,grd_sub")도 지원한다.
    // 각 grid는 접미사 옵션으로 실행을 제어한다 : "id|nofocus"(포커스 끔), "id|norefresh"(refresh/initGrid 끔). 기본은 refresh + 첫 셀 포커스 모두 실행.
    // grid.refresh()는 target DataCollection의 setJSON 시(ondataload) 호출되도록 __bindResponseToTargets에서 바인딩한다.
    let gridViews = [];
    if ($c.util.isEmpty(resObj.errorType) && sbmObj._gridview) {
        const $p = sbmObj.getScopeWindow().$p;
        // gridview를 grid별 { gv, refresh, focus } 디스크립터로 파싱/구성한다.
        gridViews = scwin.__parseGridview(sbmObj._gridview).map(function (spec) {
            const gv = (typeof spec.ref === "string") ? $p.getComponentById(spec.ref) : spec.ref;
            if (!gv) { return null; }
            return { gv: gv, refresh: spec.refresh, focus: spec.focus };
        }).filter(Boolean);
        // refresh 대상 grid만 initGrid()로 초기화한다.(norefresh grid는 이 메커니즘이 건드리지 않음)
        gridViews.forEach(function (entry) {
            if (entry.refresh && entry.gv && (typeof entry.gv.initGrid === "function")) {
                entry.gv.initGrid();
            }
        });
    }

    // executeDynamic 간소화 target 자동 바인딩 : 통신 성공 시 응답 본문을 대상 DataCollection에 적재한다.
    // (done 핸들러/Promise resolve 이전에 수행하여 후속 핸들러가 적재된 데이터를 참조할 수 있게 한다.)
    if ($c.util.isEmpty(resObj.errorType) && !$c.util.isEmpty(sbmObj._autoBindTargets)) {
        scwin.__bindResponseToTargets(sbmObj, resObj, sbmObj._autoBindTargets, gridViews);
    }

    if ($c.util.isEmpty(resObj.errorType) && typeof sbmObj._promise_submitDoneHandler === "function") {
        sbmObj._promise_submitDoneHandler(resObj);
    } else if (!$c.util.isEmpty(resObj.errorType) && typeof sbmObj._promise_submitErrorHandler === "function") {
        sbmObj._promise_submitErrorHandler(resObj);
    }

    const rsJSON = resObj.responseJSON || null;
    if (rsJSON && rsJSON.rsMsg) {
        $c.sbm.resultMsg(rsJSON.rsMsg);
    }
};

/**
 * @method
 * @name __submitErrorHandler
 * @description submission중 에러가 발생한 경우 호출되는 함수 - 서버 오류(500 error)
 * @param {Object} resObj responseData 객체
 * @hidden N
 * @exception 
 */
scwin.__submitErrorHandler = function (resObj) {
    const $p = $c.win.__getScope(resObj.id).scwin.$w;

    let detailStr = "HTTP STATUS INFO";
    detailStr += resObj.responseReasonPhrase;
    detailStr += " ";
    detailStr += resObj.responseStatusCode;
    detailStr += "URI:";
    detailStr += resObj.resourceUri;
    detailStr += resObj.responseBody;

    const message = ($c.util.isEmpty(resObj.message)) ? "서버 오류입니다. 자세한 내용은 관리자에게 문의하시기 바랍니다." : resObj.message;

    const msgObj = {
        statusCode: "E",
        errorCode: "E9998",
        message: message,
        messageDetail: detailStr                                                                                                                                                                                                                                                                                             
    };

    $c.sbm.resultMsg(msgObj);
};


/**
 * @method
 * @name __applyDuplicateGuard
 * @description 중복 실행 제어 가드. 비동기 통신이 진행 중(processStatus === 1)인 submission에 대해
 * allowDuplicate / onDuplicate 옵션에 따라 실행 여부를 판정한다. execute / executeDynamic 공통 로직.
 * - allowDuplicate가 true이거나 진행 중이 아니면 { skip:false } 반환(정상 실행).
 * - 진행 중 + onDuplicate "abort" : 진행 중 요청을 취소하고 직전 Promise를 reject한 뒤 { skip:false } 반환(재실행).
 * - 진행 중 + onDuplicate "ignore"(기본) : { skip:true, result } 반환(이번 호출 건너뜀).
 * @param {Object} sbmObj submission 객체
 * @param {Object} execOptions 중복 실행 제어 옵션 (allowDuplicate / onDuplicate)
 * @returns {Object} { skip:Boolean, result:Object } skip이 true면 호출자는 result로 즉시 종료한다.
 * @hidden Y
 * @exception
 */
scwin.__applyDuplicateGuard = function (sbmObj, execOptions) {
    execOptions = execOptions || {};

    const allowDuplicate = (execOptions.allowDuplicate === true) || (sbmObj.allowDuplicate === true);

    if ((allowDuplicate === false) && (sbmObj.processStatus === 1)) {
        if (execOptions.onDuplicate === "abort") {
            // 후행 우선 : 진행 중 요청을 취소한다. (abort는 setSubmissionEnd를 동기 호출하여 processStatus를 0으로 리셋)
            WebSquare.ModelUtil.abort(sbmObj.id, sbmObj.scope_id);
            // abort는 defaultCallback(__callbackSubmitFunction)을 호출하지 않으므로, 취소된 직전 Promise를 수동으로 reject 처리한다.
            if (typeof sbmObj._promise_submitErrorHandler === "function") {
                sbmObj._promise_submitErrorHandler({ aborted: true, reason: "duplicate-abort", id: sbmObj.id });
            }
            // 취소된 직전 Promise의 핸들러를 정리한다. (엔진 이벤트 경로 등에서 동일 핸들러가 재호출되어 다음 요청의 Promise를 잘못 settle하는 것을 방지)
            sbmObj._promise_submitDoneHandler = null;
            sbmObj._promise_submitErrorHandler = null;
            return { skip: false };
        }
        // 선행 우선(기본) : 진행 중 요청을 유지하고 이번 호출은 건너뛴다.
        return { skip: true, result: { skipped: true, reason: "duplicate", id: sbmObj.id } };
    }

    return { skip: false };
};


/**
 * @method
 * @name execute
 * @description 서버 통신 확장 모듈, Submission를 실행합니다.
 *  requestData를 전달하지 않은 경우, submission의 ref가 단건 DataCollection(DataMap)을 가리키면
 *  해당 DataMap의 데이터 객체를 추출해 ref 대신 requestData로 전달한다.
 * @param {Object} sbmObj submission 객체
 * @param {Object} requestData [Default : null, JSON, XML] 요청 데이터로 submission에 등록된 ref를 무시하고 현재의 값이 할당된다.
 * @param {Object} compObj [Default : null] 전송중 disable시킬 컴포넌트
 * @param {Object} options [Default : null] 중복 실행 제어 옵션
 * @param {Boolean} options.allowDuplicate [Default : false] true이면 진행 중인 통신과 무관하게 중복 실행을 허용한다.
 *  (submission 객체에 sbmObj.allowDuplicate = true 로 설정해도 동일하게 동작한다.)
 * @param {String} options.onDuplicate [Default : "ignore"] allowDuplicate가 false이고 통신이 진행 중일 때의 처리 정책.
 *  - "ignore" : (기본/선행 우선) 진행 중 요청을 유지하고 이번 호출은 건너뛴다. 더블클릭/연타 방지에 사용. (반환 Promise는 { skipped:true }로 resolve)
 *  - "abort"  : (후행 우선) 진행 중 요청을 취소하고 이번 요청을 실행한다. 검색어 자동완성 등 최신 요청만 의미 있을 때 사용.
 *               취소된 직전 요청의 Promise는 { aborted:true, reason:"duplicate-abort" }로 reject된다.
 * @hidden N
 * @exception
 * @example
// Submission의 ref 속성에 서버에 전송할 DataCollection을 설정하는 경우
$c.sbm.execute(sbm_search);

//  Submission의 ref 속성에 서버에 전송할 DataCollection을 설정하지 않고 JSON 객체를 전송하는 경우
const searchParam = {
    id : "A0001"
};
$c.sbm.execute(sbm_search, searchParam);

// 더블클릭 방지 : 저장 통신이 끝나기 전까지 재호출을 무시한다. (선행 우선)
$c.sbm.execute(sbm_save, null, btn_save, { allowDuplicate: false });

// 최신 요청만 처리 : 진행 중 요청을 취소하고 새 요청을 실행한다. (후행 우선)
$c.sbm.execute(sbm_search, searchParam, null, { onDuplicate: "abort" });

// allowDuplicate와 onDuplicate를 동시에 설정하는 경우 : allowDuplicate가 우선한다.
// allowDuplicate가 true이면 중복 실행을 허용하므로 onDuplicate("abort")는 무시되고, 진행 중 요청을 취소하지 않고 그대로 동시 실행한다.
$c.sbm.execute(sbm_search, searchParam, null, { allowDuplicate: true, onDuplicate: "abort" });

// ignore(기본) 정책에서 중복으로 건너뛴 호출은 응답 없이 { skipped:true }로 resolve된다.
// 응답 데이터를 사용하는 then 체인에서는 skipped를 먼저 확인해 후속 처리를 중단해야 한다.
$c.sbm.execute(sbm_save).then(function (res) {
    if (res && res.skipped) { return; } // 진행 중 통신이 있어 이번 호출은 건너뜀
    // ... 정상 응답 처리 ...
});

// async/await 사용 시에도 동일하게 skipped를 먼저 확인한다.
scwin.btn_save_onclick = async function (e) {
    const res = await $c.sbm.execute(sbm_save);
    if (res && res.skipped) { return; } // 진행 중 통신이 있어 이번 호출은 건너뜀
    // ... 정상 응답 처리 ...
};
 */
scwin.execute = function (sbmObj, requestData, compObj, options) {
    options = options || {};
    return new Promise(function (resolve, reject) {
        if (typeof sbmObj !== "object" || $c.util.isEmpty(sbmObj)) {
            // submission 객체가 아니면 Promise가 영구 pending 되지 않도록 reject 처리한다.
            reject($c.data.getMessage("MSG_CM_00002", "submission"));
            return;
        }

        const _sbmObj = sbmObj;

        if ($c.util.isEmpty(_sbmObj.action)) {
            const alertMsg = $c.data.getMessage("MSG_CM_00002", "action");
            $c.win.alert(alertMsg);
            reject(alertMsg);
            return;
        }

        // 동기(synchronous) 모드에서는 통신이 블로킹되어 재호출 시점에 이미 processStatus가 0으로 복귀하므로
        // 중복 실행 가드가 동작하지 않는다(비동기 모드에서만 유효). 개발자에게 무효임을 알리는 경고 로그를 항상 출력한다.
        if (_sbmObj.mode === "synchronous") {
            console.warn("[$c.sbm.execute] 동기(synchronous) 모드에서는 중복 실행 제어(allowDuplicate/onDuplicate)가 동작하지 않습니다. submission id: " + _sbmObj.id + ", action: " + _sbmObj.action);
        }

        // 중복 실행 제어 가드 (비동기 통신 진행 중 재호출 처리). skip이면 이번 호출을 건너뛰고 즉시 종료한다.
        const guard = scwin.__applyDuplicateGuard(_sbmObj, options);
        if (guard.skip === true) {
            resolve(guard.result);
            return;
        }

        if ($c.util.isEmpty(_sbmObj.submitDoneHandler)) {
            _sbmObj._promise_submitDoneHandler = function (rtn) {
                resolve(rtn);
            }
        }

        if ($c.util.isEmpty(_sbmObj.submitErrorHandler)) {
            _sbmObj._promise_submitErrorHandler = function (rtn) {
                reject(rtn);
            }
        }

        // requestData가 비어 있고 ref가 단건 DataCollection(DataMap)을 가리키면,
        // 해당 DataMap의 데이터 객체만 추출해 ref 대신 requestData 인자로 전달한다.
        if ($c.util.isEmpty(requestData) && ($c.util.isEmpty(_sbmObj.ref) === false) && (_sbmObj.ref.indexOf("data:json,") === 0)) {
            const refDcId = _sbmObj.ref.substring("data:json,".length).trim();
            // 단순 단일 DataCollection ID(배열/객체/필드경로 표기 제외)인 경우만 처리한다.
            if (/^[A-Za-z_$][\w$]*$/.test(refDcId)) {
                const refDc = $p.getComponentById(refDcId);
                if (refDc && (typeof refDc.getObjectType === "function") && (refDc.getObjectType().toLowerCase() === "datamap")) {
                    requestData = refDc.getJSON();
                }
            }
        }

        $p.executeSubmission(_sbmObj, requestData, compObj);
    });
};


/**
 * @method
 * @name __normalizeRefTarget
 * @description executeDynamic 옵션의 간소화된 ref/target 문자열을 처리한다.
 *  - 이미 "data:" 로 시작하거나 비어 있으면 변환하지 않는다(하위 호환). 이 경우 ref/target은 엔진이 직접 바인딩한다.
 *  - 항목은 콤마(,)로 구분하며, 각 항목에 "id=key" 형식으로 key를 지정할 수 있다. (key는 점(.) 경로 허용. 예: "body.content")
 *  - ref    : 서버로 보낼 DataCollection ID → WebSquare 표준 표현식(data:json,...)으로 변환한다(요청 측, 엔진 처리).
 *      "dma_a"            → data:json,dma_a
 *      "dma_a=body"      → data:json,{"id":"dma_a","key":"body"}
 *      "dma_a,dlt_b"      → data:json,["dma_a","dlt_b"]
 *  - target : 응답을 받을 DataCollection ID. 항목별 "|append" 로 Append 모드를 지정한다.
 *      응답 본문을 직접 적재(setJSON)하기 위해 바인딩 디스크립터로 파싱하여 options.__bindTargets에 보관하고,
 *      엔진 중복 바인딩(double-bind)을 막기 위해 options.target은 비운다. 실제 적재는 $c.sbm.__bindResponseToTargets에서 수행한다.
 *      key가 지정되면 responseJSON.<key> 값을, 없으면 응답 본문(responseJSON.body)을 적재한다.
 *      "dlt_a"                    → [{id:"dlt_a"}]
 *      "dlt_a=body.content"       → [{id:"dlt_a", key:"body.content"}]
 *      "dlt_a|append"             → [{id:"dlt_a", append:true}]
 *      "dlt_a,dlt_b=body.x|append" → [{id:"dlt_a"},{id:"dlt_b", key:"body.x", append:true}]
 * @param {Object} options executeDynamic/create 옵션 객체. ref는 in-place로 변환하고, 간소화 target은 __bindTargets로 분리한다.
 * @hidden Y
 * @exception
 */
scwin.__normalizeRefTarget = function (options) {
    // ref : "id" 또는 "id=key" 를 콤마로 구분 → data:json 표현식 (요청 측, 엔진이 바인딩)
    if (($c.util.isEmpty(options.ref) === false) && (options.ref.indexOf("data:") !== 0)) {
        const refItems = options.ref.split(",").map(function (token) { return token.trim(); }).filter(Boolean).map(function (token) {
            const idKey = token.split("=");
            const id = idKey[0].trim();
            const key = (idKey.length > 1) ? idKey[1].trim() : "";
            // key가 없으면 ID 문자열, 있으면 {id, key} 객체로 표현한다.
            return ($c.util.isEmpty(key) === false) ? { id: id, key: key } : id;
        });
        options.ref = (refItems.length === 1)
            ? "data:json," + ((typeof refItems[0] === "string") ? refItems[0] : JSON.stringify(refItems[0]))
            : "data:json," + JSON.stringify(refItems);
    }

    // target : "id[=key][|append]" → 응답 본문을 직접 적재할 바인딩 디스크립터로 분리 (응답 측, 수동 바인딩)
    if (($c.util.isEmpty(options.target) === false) && (options.target.indexOf("data:") !== 0)) {
        options.__bindTargets = options.target.split(",").map(function (token) {
            const parts = token.split("|");
            const idKey = parts[0].split("=");
            const targetObj = { id: idKey[0].trim() };
            if ((idKey.length > 1) && ($c.util.isEmpty(idKey[1].trim()) === false)) {
                targetObj.key = idKey[1].trim();
            }
            if ((parts.length > 1) && (parts[1].trim() === "append")) {
                targetObj.append = true;
            }
            return targetObj;
        }).filter(function (t) { return $c.util.isEmpty(t.id) === false; });
        // 엔진 target 바인딩과의 중복 적재를 막기 위해 표준 target은 비운다.
        options.target = "";
    }
};

/**
 * @method
 * @name __parseGridview
 * @description executeDynamic options.gridview 값을 grid별 디스크립터 { ref, refresh, focus } 배열로 파싱한다.
 *  ref는 컴포넌트 ID 문자열 또는 컴포넌트 객체. refresh/focus는 기본 true이며, 접미사 옵션으로 끈다.
 *  - 접미사 옵션 : "id|nofocus"(focus 끔), "id|norefresh"(refresh 끔). 한 grid에 여러 옵션은 "id|nofocus,norefresh".
 *  - 문자열에서 콤마(,)는 grid 구분자이자 옵션 구분자를 겸하므로 연속(continuation) 파싱한다.
 *    예약 키워드(nofocus/norefresh) 단독 토큰은 직전 grid의 추가 옵션으로 이어붙인다.
 *    "grd_main|nofocus,norefresh,grd_sub|norefresh" → grd_main{F,F}, grd_sub{refresh:F, focus:T}
 *  - 배열은 각 요소가 자체 완결 토큰("id|opt,opt") 또는 컴포넌트 객체. 단일 컴포넌트 객체는 기본값으로 처리한다.
 * @param {String|Object|Array} gridviewRef options.gridview 값
 * @returns {Array} [{ ref:(String|Object), refresh:Boolean, focus:Boolean }]
 * @hidden Y
 * @exception
 */
scwin.__parseGridview = function (gridviewRef) {
    const makeEntry = function (ref) { return { ref: ref, refresh: true, focus: true }; };
    const applyOpt = function (entry, opt) {
        opt = (opt || "").trim().toLowerCase();
        if (opt === "nofocus") { entry.focus = false; }
        else if (opt === "norefresh") { entry.refresh = false; }
    };
    // 컴포넌트 객체(옵션 문법 없음) → 기본값
    if ((typeof gridviewRef !== "string") && ($c.util.isArray(gridviewRef) === false)) {
        return [makeEntry(gridviewRef)];
    }
    // 배열 : 각 요소가 자체 완결 토큰("id|opt,opt") 또는 컴포넌트
    if ($c.util.isArray(gridviewRef)) {
        return gridviewRef.map(function (el) {
            if (typeof el !== "string") { return makeEntry(el); }
            const parts = el.split(/[|,]/).map(function (s) { return s.trim(); }).filter(Boolean);
            const entry = makeEntry(parts[0]);
            parts.slice(1).forEach(function (o) { applyOpt(entry, o); });
            return entry;
        }).filter(function (e) { return $c.util.isEmpty(e.ref) === false; });
    }
    // 문자열 : 콤마가 grid/옵션 구분자 겸용 → 연속(continuation) 파싱
    const RESERVED = { nofocus: true, norefresh: true };
    const entries = [];
    gridviewRef.split(",").map(function (s) { return s.trim(); }).filter(Boolean).forEach(function (tok) {
        const isOptOnly = (tok.indexOf("|") < 0) && (RESERVED[tok.toLowerCase()] === true);
        if (isOptOnly && (entries.length > 0)) {
            applyOpt(entries[entries.length - 1], tok); // 직전 grid 옵션 이어붙임
        } else {
            const parts = tok.split("|").map(function (s) { return s.trim(); }).filter(Boolean);
            const entry = makeEntry(parts[0]);
            parts.slice(1).forEach(function (o) { applyOpt(entry, o); });
            entries.push(entry);
        }
    });
    return entries;
};

/**
 * @method
 * @name __bindResponseToTargets
 * @description executeDynamic 간소화 target으로 분리된 바인딩 디스크립터에 따라, 통신 응답을
 *  대상 DataCollection에 직접 적재한다.
 *  - key가 지정된 target은 responseJSON.<key>(점(.) 경로) 값을 적재한다. (예: key="body.content" → responseJSON.body.content)
 *  - key가 없는 target은 응답 본문(body 래퍼 우선, 없으면 평면 responseJSON)을 기준으로 적재한다.
 *    본문이 배열이면 선언 순서대로 순차 매핑(body[i] → targets[i]), 단일 객체이면 첫 번째 target에 적재한다.
 *  - 각 target의 append가 true이면 기존 데이터를 유지하며 추가한다. (setJSON(data, true))
 * @param {Object} sbmObj Submission 객체 (scope window의 $p를 도출하는 데 사용)
 * @param {Object} rtn 통신 응답 객체 (rtn.responseJSON 에 실데이터)
 * @param {Array} targets 바인딩 디스크립터 배열 [{id, key, append}]
 * @param {Array} gridViews [Default : []] { gv:컴포넌트, refresh:Boolean, focus:Boolean } 디스크립터 배열. 지정 시, setJSON으로 데이터가 로드되는 각 target DataCollection의
 *  ondataload 이벤트 핸들러를 1회만 바인딩한다(중복 등록 방지). 핸들러는 entry.refresh가 true면 gv.refresh()를, entry.focus가 true이고 로드된 데이터가 있으면 gv.setFocusedCell(0,0)으로 첫 셀에 포커스한다. 다중 gridView를 지원한다.
 * @hidden Y
 * @exception
 */
scwin.__bindResponseToTargets = function (sbmObj, rtn, targets, gridViews) {
    const $p = sbmObj.getScopeWindow().$p;

    if ($c.util.isEmpty(targets) || $c.util.isEmpty(rtn) || $c.util.isEmpty(rtn.responseJSON)) {
        return;
    }

    const responseJSON = rtn.responseJSON;

    // 대상 DataCollection에 데이터를 적재하는 내부 헬퍼 (data가 undefined면 적재하지 않음)
    const bindOne = function (id, data, append) {
        if (typeof data === "undefined") {
            return;
        }
        const dc = $p.getComponentById(id);
        if (!dc || typeof dc.setJSON !== "function") {
            return;
        }
        // gridView(들) 지정 시 : setJSON으로 데이터가 로드(ondataload)될 때 각 grid.refresh()가 호출되도록 이벤트를 1회만 바인딩한다.
        // (handler는 dc.__gridviewsToRefresh를 참조하므로, 매 호출마다 최신 gridView 목록으로 갱신하되 bind는 중복 등록하지 않는다.)
        if (gridViews && gridViews.length > 0 && typeof dc.bind === "function") {
            dc.__gridviewsToRefresh = gridViews;
            if (dc.__gridviewRefreshBound !== true) {
                dc.bind("ondataload", function () {
                    const gvs = dc.__gridviewsToRefresh || [];
                    // 데이터가 있을 때만 첫 셀 포커스(setFocusedCell)를 적용한다.(빈 그리드 가드)
                    const hasRows = (typeof dc.getRowCount === "function") && (dc.getRowCount() > 0);
                    // grid별 refresh/focus 플래그를 각각 독립 적용한다.(norefresh→refresh 생략, nofocus→포커스 생략)
                    gvs.forEach(function (entry) {
                        if (!entry.gv) { return; }
                        if (entry.refresh && (typeof entry.gv.refresh === "function")) {
                            entry.gv.refresh();
                        }
                        if (entry.focus && hasRows && (typeof entry.gv.setFocusedCell === "function")) {
                            entry.gv.setFocusedCell(0, 0);
                        }
                    });
                });
                dc.__gridviewRefreshBound = true;
            }
        }
        dc.setJSON(data, append === true);
    };

    // key가 지정된 target은 responseJSON.<key>(점 경로) 값을 직접 적재하고, 나머지는 본문 기반으로 적재한다.
    const plainTargets = [];
    targets.forEach(function (t) {
        if ($c.util.isEmpty(t.key) === false) {
            let val = responseJSON;
            const keyPath = t.key.split(".");
            for (let i = 0; (i < keyPath.length) && (val !== null) && (typeof val !== "undefined"); i++) {
                val = val[keyPath[i]];
            }
            bindOne(t.id, val, t.append);
        } else {
            plainTargets.push(t);
        }
    });

    if (plainTargets.length === 0) {
        return;
    }

    // 응답 본문 : body 래퍼가 있으면 그 값을, 없으면 평면 응답(responseJSON)을 사용한다.
    const body = (typeof responseJSON.body !== "undefined") ? responseJSON.body : responseJSON;
    if ($c.util.isEmpty(body)) {
        return;
    }

    if ($c.util.isArray(body)) {
        // 배열 → 선언 순서대로 target에 순차 매핑
        plainTargets.forEach(function (t, i) {
            bindOne(t.id, body[i], t.append);
        });
    } else {
        // 단일 객체 → 첫 번째 target에 적재
        bindOne(plainTargets[0].id, body, plainTargets[0].append);
    }
};


/**
 * @method
 * @name executeDynamic
 * @description Submission를 동적으로 생성해서 실행합니다.
 *  options.ref / options.target 은 간소화 문법을 지원한다. DataCollection ID만 콤마(,)로 구분해서 전달하면,
 *  ref는 WebSquare 표준 표현식(data:json,...)으로 변환되어 요청에 사용되고, target은 통신 성공 시 응답 본문(responseJSON.body)을
 *  선언 순서대로 대상 DataCollection에 직접 적재한다. (본문이 배열이면 순차 매핑, 단일 객체면 첫 target) target 항목에 "|append" 를
 *  붙이면 기존 데이터를 유지하며 추가한다(setJSON(data, true)). "data:" 로 시작하는 기존 표현식을 그대로 넘기면 엔진이 직접 바인딩한다.
 *  자세한 규칙은 scwin.__normalizeRefTarget / scwin.__bindResponseToTargets 참고.
 *  options.gridview 를 지정하면 통신 성공 시 refresh 대상 grid에 grid.initGrid()를 호출하고, target DataCollection의 데이터 로드(ondataload) 시 grid.refresh()와 첫 셀 포커스(setFocusedCell(0,0))를 수행한다.
 *  gridview는 콤마(,)로 구분한 다중 ID 문자열("grd_main,grd_sub")을 지원한다. grid별 접미사 옵션으로 실행을 제어한다 : "id|nofocus"(포커스 끔), "id|norefresh"(refresh/initGrid 끔), "id|nofocus,norefresh"(둘 다 끔). 옵션 미지정 시 refresh + 첫 셀 포커스 모두 실행한다.
 * @param {Object} options $c.sbm.create의 options 참고
 * @param {String|Object} options.gridview [Default : null] 통신 성공 시 처리할 gridView. 컴포넌트 ID 문자열(콤마로 구분한 다중 ID 가능, grid별 "|nofocus"/"|norefresh" 접미사 옵션 지원) 또는 컴포넌트 객체. 기본은 refresh 대상 grid initGrid() 호출, target DataCollection의 ondataload 시 refresh() + setFocusedCell(0,0) 호출.
 * @param {Object} requestData 요청 데이터
 * @param {Object} obj 전송중 disable시킬 컴퍼넌트
 * @param {Object} execOptions [Default : null] 중복 실행 제어 옵션. $c.sbm.execute의 options 참고(allowDuplicate / onDuplicate).
 *  executeDynamic은 매 호출마다 submission을 재생성하므로, 가드는 재생성 전의 기존 submission 객체(진행 중 통신)에서 판정한다.
 *  동기(synchronous) 모드에서는 통신이 블로킹되어 가드가 동작하지 않으며, 이 경우 $c.sbm.execute에서 콘솔 경고 로그가 출력된다.
 * @hidden N
 * @exception
 * @example
// 간소화 문법 : DataCollection ID만 콤마(,)로 구분하고, 응답을 추가(Append)할 대상에는 "|append" 를 붙인다.
// 통신 성공 시 응답 본문(responseJSON.body)이 선언 순서대로 [dlt_commonGrp, dlt_commonCode, dlt_commonSearchItem(append)] 에 적재된다.
const sbmOptions = {
     id : "sbm_SelectTempDynamic",
     action : "/sample/tempSelect",
     ref : "dma_search",
     target : "dlt_commonGrp,dlt_commonCode,dlt_commonSearchItem|append",
     submitDoneHandler : scwin.sbm_SelectTemp_submitdone, isProcessMsg : false };
$c.sbm.executeDynamic(sbmOptions);

// gridview : 통신 성공 시 자동 바인딩 직전 grid.initGrid() 호출, target DataCollection 데이터 로드(ondataload) 시 grid.refresh() 호출. (ID 문자열 또는 컴포넌트 객체)
const sbmOptions = {
     id : "sbm_SelectTempDynamic",
     action : "/sample/tempSelect",
     ref : "dma_search",
     target : "dlt_commonGrp",
     gridview : "grd_main", // 또는 gridview : grd_main
     isProcessMsg : false };
$c.sbm.executeDynamic(sbmOptions);

// 다중 gridview : 콤마(,)로 구분하면 여러 grid를 함께 처리한다. (각 grid initGrid() 호출, target 데이터 로드 시 각 grid refresh() 호출)
const sbmOptions = {
     id : "sbm_SelectTempDynamic",
     action : "/sample/tempSelect",
     ref : "dma_search",
     target : "dlt_commonGrp,dlt_commonCode",
     gridview : "grd_main,grd_sub", // 콤마로 다중 gridview 설정
     isProcessMsg : false };
$c.sbm.executeDynamic(sbmOptions);

// gridview 접미사 옵션 : grid별로 refresh()/setFocusedCell(0,0) 실행을 제어한다. (기본은 둘 다 실행)
// "id|nofocus"(포커스 끔), "id|norefresh"(refresh/initGrid 끔), "id|nofocus,norefresh"(둘 다 끔)
const sbmOptions = {
     id : "sbm_SelectTempDynamic",
     action : "/sample/tempSelect",
     ref : "dma_search",
     target : "dlt_commonGrp,dlt_commonCode",
     gridview : "grd_main,grd_sub|nofocus", // grd_main : refresh + 포커스, grd_sub : refresh만(포커스 생략)
     isProcessMsg : false };
$c.sbm.executeDynamic(sbmOptions);

// id=key 간소화 문법 : 각 항목에 "id=key"로 응답 경로(key, 점(.) 경로 허용)를 지정한다.
const sbmOptions = {
     id : "sbm_SelectTempDynamic",
     action : "/sample/tempSelect",
     ref : "dma_search=body",
     target : "dlt_commonGrp=body.content",
     gridview : grd_main,
     submitDoneHandler : scwin.sbm_SelectTemp_submitdone, isProcessMsg : false };
$c.sbm.executeDynamic(sbmOptions);
// 통신 성공 시 dlt_commonGrp.setJSON(rtn.responseJSON.body.content) 으로 적재된다.

// 진행 중 요청을 취소하고 최신 요청으로 재실행 (후행 우선)
$c.sbm.executeDynamic(sbmOptions, null, null, { onDuplicate: "abort" });

// 더블클릭 방지 : 진행 중 통신이 끝나기 전까지 재호출을 무시한다. (선행 우선)
$c.sbm.executeDynamic(sbmOptions, null, null, { allowDuplicate: false });

// allowDuplicate와 onDuplicate를 동시에 설정하는 경우 : allowDuplicate가 우선한다.
// allowDuplicate가 true이면 중복 실행을 허용하므로 onDuplicate("abort")는 무시되고, 진행 중 요청을 취소하지 않고 그대로 동시 실행한다.
$c.sbm.executeDynamic(sbmOptions, null, null, { allowDuplicate: true, onDuplicate: "abort" });

// ignore(기본) 정책에서 중복으로 건너뛴 호출은 응답 없이 { skipped:true }로 resolve된다.
// 응답 데이터를 사용하는 then 체인에서는 skipped를 먼저 확인해 후속 처리를 중단해야 한다.
$c.sbm.executeDynamic(sbmOptions).then(function (res) {
    if (res && res.skipped) { return; } // 진행 중 통신이 있어 이번 호출은 건너뜀
    // ... 정상 응답 처리 ...
});

// async/await 사용 시에도 동일하게 skipped를 먼저 확인한다.
scwin.btn_search_onclick = async function (e) {
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return; } // 진행 중 통신이 있어 이번 호출은 건너뜀
    // ... 정상 응답 처리 ...
};
 */
scwin.executeDynamic = function (options, requestData, obj, execOptions) {
    execOptions = execOptions || {};

    // 간소화된 ref/target 문자열을 WebSquare 표준 표현식(data:json,...)으로 변환한다. (create 호출 전에 수행)
    scwin.__normalizeRefTarget(options);

    let submissionObj = $c.util.getComponent(options.id);

    // 중복 실행 제어 : executeDynamic은 매 호출마다 submission을 삭제/재생성(processStatus 0으로 초기화)하므로,
    // 가드는 재생성 전의 기존 객체에서 판정한다. skip이면 재생성/실행 없이 즉시 종료한다.
    if (submissionObj !== null) {
        const guard = scwin.__applyDuplicateGuard(submissionObj, execOptions);
        if (guard.skip === true) {
            return Promise.resolve(guard.result);
        }
    }

    if (submissionObj === null) {
        $c.sbm.create(options);
        submissionObj = $c.util.getComponent(options.id);
    } else {
        $p.deleteSubmission(options.id);
        $c.sbm.create(options);
        submissionObj = $c.util.getComponent(options.id);
    }

    // 간소화 target으로 분리된 바인딩 디스크립터를 submission 객체에 부착한다.
    // 통신 성공 시 공통 콜백($c.sbm.__callbackSubmitFunction)에서 응답 본문을 대상 DataCollection에 적재한다.
    if (($c.util.isEmpty(options.__bindTargets) === false) && (submissionObj !== null)) {
        submissionObj._autoBindTargets = options.__bindTargets;
    }

    // gridview가 지정되면 submission 객체에 부착한다.
    // 통신 성공 시 공통 콜백에서 refresh 대상 grid에 grid.initGrid()를 호출하고,
    // target DataCollection의 ondataload 이벤트에서 grid.refresh()/setFocusedCell()이 호출되도록 한다.
    // grid별 접미사 옵션(|nofocus, |norefresh)으로 실행을 제어한다. (컴포넌트 ID 문자열 또는 컴포넌트 객체)
    if (options.gridview && (submissionObj !== null)) {
        submissionObj._gridview = options.gridview;
    }

    return $c.sbm.execute(submissionObj, requestData, obj, execOptions);
};

/**
