/**
 * @method
 * @name setPagingInfo
 * @description 페이징 옵션(pagingInfo)을 기본값과 병합하고, 조회 DataMap(inData) 에
 *  currentPage / recordCountPerPage 컬럼을 설정한다.
 *  totalCnt 가 전달되면 페이지 리스트 컴포넌트(pageListComponent) 렌더링까지 수행한다.
 *  (commonScope.js com.gfnExecute 의 페이징 옵션 + pageListComponent 처리 로직 분리)
 * @param {Object} pagingInfo 페이징 옵션 객체 (sbmOptions.pagingInfo 가 아닌 값 자체)
 * @param {String} inData (선택) submission inData 문자열. 조회 DataMap 컬럼 설정에 사용
 * @param {Number} totalCnt (선택) 전체 건수. 전달 시 pageListComponent 렌더링 수행
 * @returns {Object} 기본값이 병합된 pagingInfo (pagingInfo 미설정 시 빈 객체 {})
 * @hidden N
 * @exception
 * @example
const pagingInfo = {
    pageType : "P",                 // S/P/A
    pageListId : "pglList",         // 페이지 리스트 아이디
    pageFunction : "scwin.fnSrch",  // 페이징 처리 함수
    currentPage : 1,                // 현재 페이지
    totalCountId : "tbxTotCnt",     // total count 출력 아이디
    recordCountPerPage : 20         // 한 페이지에 보여줄 라인 수
};
// 통신 전: 기본값 병합 + DataMap 컬럼 설정
$c.sbm.setPagingInfo(pagingInfo, "dataM=dlSearchM");
// 통신 후: 전체 건수로 페이지 리스트 렌더링
$c.sbm.setPagingInfo(pagingInfo, null, 135);
 */
scwin.setPagingInfo = function (pagingInfo, inData, totalCnt) {
    // 페이징 옵션이 없으면 빈 객체 반환
    if ($c.util.isEmpty(pagingInfo)) {
        return {};
    }

    const pagingDefault = {
        /* 필수 */
        pageType : "",            // S/P/A
        pageFunction : "",        // 페이징 처리 하는 함수
        currentPage : 1,          // 현재 페이지

        /* pageType:P 시 필수 */
        pageListId : "",          // 페이지 리스트 아이디

        /* pageType:S 시 필수 */
        gridId : "",              // 그리드 아이디

        /* 선택 */
        totalCountId : "",        // total count 를 출력할 아이디
        recordCountPerPage : "",  // 한 페이지에 보여줄 라인 수
        pageSize : 10             // 페이징 시 출력해줄 페이지 번호 개수
    };

    pagingInfo = $c.util.assignDefined(pagingDefault, pagingInfo);

    // 모바일 환경일 경우 pageSize 5로 변경
    pagingInfo.pageSize = ($c.util.isMobile()) ? 5 : pagingInfo.pageSize;

    // 조회 Map 키를 inData 첫 토큰에서 추출 (dataM=dataViewM → dataViewM)
    if (!$c.util.isEmpty(inData)) {
        let inDataKey = inData.split(" ")[0];
        inDataKey = (inDataKey.split("=").length > 1) ? inDataKey.split("=")[1] : inDataKey.split("=")[0];

        const inDataMap = $p.getComponentById(inDataKey);
        if (!$c.util.isEmpty(inDataMap)) {
            // DataMap 에 currentPage, recordCountPerPage 컬럼이 없으면 추가
            if (typeof inDataMap.get("currentPage") === "undefined") {
                inDataMap.addColumn({ id : "currentPage", name : "현재 페이지", dataType : "text", value : "" });
            }
            if (typeof inDataMap.get("recordCountPerPage") === "undefined") {
                inDataMap.addColumn({ id : "recordCountPerPage", name : "한 페이지에 보여줄 라인 수", dataType : "text", value : "" });
            }

            inDataMap.set("currentPage", pagingInfo.currentPage);

            // recordCountPerPage 결정 (옵션 지정 > Map 기존값 > 기본 10)
            if (!$c.util.isEmpty(pagingInfo.recordCountPerPage)) {
                inDataMap.set("recordCountPerPage", pagingInfo.recordCountPerPage);
            } else if (!$c.util.isEmpty(inDataMap.get("recordCountPerPage"))) {
                pagingInfo.recordCountPerPage = inDataMap.get("recordCountPerPage");
            } else {
                pagingInfo.recordCountPerPage = 10;
            }
        }
    }

    // totalCnt 가 전달되면 페이지 리스트(pageListComponent) 렌더링
    if (!$c.util.isEmpty(totalCnt) && !$c.util.isEmpty(pagingInfo.pageListId)) {
        const outTotalCnt = Math.ceil(totalCnt / pagingInfo.recordCountPerPage);
        const selectCurrentPage = pagingInfo.currentPage;

        pagingInfo.pageListId.split(",").forEach(function (id) {
            const pageListComponent = $p.getComponentById(id);
            if ($c.util.isEmpty(pageListComponent)) return;

            pageListComponent.setPageSize(pagingInfo.pageSize);

            if (outTotalCnt > 1) {
                // 페이지 리스트 표시 및 페이지 변경 이벤트 등록
                pageListComponent.show();
                pageListComponent.setCount(outTotalCnt, true);
                const scopeScwin = pageListComponent.scope_obj.getObj("scwin");

                if (selectCurrentPage != 1 && selectCurrentPage <= outTotalCnt) {
                    pageListComponent.setValue(selectCurrentPage);
                } else {
                    pageListComponent.setValue(1);
                }

                pageListComponent.unbind("onviewchange");
                pageListComponent.bind("onviewchange", function (info) {
                    $p.getComponentById(pageListComponent.getID() + "_page_" + info.newSelectedIndex)?.classList.remove("w2pageList_label_selected");

                    let newSelectedIndex = info.newSelectedIndex;
                    const oldSelectedIndex = info.oldSelectedIndex;

                    const prevList = Math.ceil(oldSelectedIndex / pagingInfo.pageSize);
                    const nowList = Math.ceil(newSelectedIndex / pagingInfo.pageSize);

                    if (newSelectedIndex === 1 || (prevList === 1 && nowList === 1 && oldSelectedIndex > pagingInfo.pageSize)) {
                        newSelectedIndex = 1;
                    } else if ((prevList - 1) === nowList) {
                        newSelectedIndex = newSelectedIndex - (pagingInfo.pageSize - 1);
                    }

                    const procFuncArr = pagingInfo.pageFunction.split(".");
                    scopeScwin[procFuncArr[1]](newSelectedIndex, oldSelectedIndex);
                });
            } else {
                // 페이지 리스트 미표시
                pageListComponent.setValue(1);
                pageListComponent.setCount(1, true);
                pageListComponent.unbind("onclick");
            }
        });
    }

    return pagingInfo;
};
